logger = logging.getLogger(__name__)

# Shared functionality for interacting with SUTS via the Squish API


class ApplicationManager():

    APP_NAME_INTEGRITY = "RTDShell.exe"
    APP_NAME_CONSOLESTART = "ConsoleStart"

    '''configurable attaching method
    if Config.get("attach.direct_attach")=="true":
        APP_NAME_INTEGRITY = "RTDShell.exe"
        APP_NAME_SERVICECORE = "ServiceCore.exe"
        APP_NAME_CONSOLESTART = "ConsoleStart.exe"
    else:
        APP_NAME_INTEGRITY = "RTDShell"
        APP_NAME_SERVICECORE = "ServiceCore"
        APP_NAME_CONSOLESTART = "ConsoleStart"
   '''

    # ToT=Yes
    @staticmethod
    def use_application_context(application_name, host=None, port=None):
        #         Changes Application Context to the given application.
        #
        #         If the application currently exists in the application context then
        #         the context will be set to that, otherwise Squish will attempt to start
        #         the requested application.
        #
        #         Args:
        #             application_name (str): The application to switch to.
        #             host (str): The host to start on (optional).
        #             port (str): The port to start on (optional)
        #
        #         Returns:
        #             No return value.

        appCtxs = sq.applicationContextList()
        no_start_list = Config.get("application.no_auto_start").split(",")
        found = False
        # Get host address and port from sharedconfig file
        host_ip = Config.get("attach.host")
        host_port = Config.get_as_int("attach.port")
        for ctx in appCtxs:
            '''seems to behave differently from unity, so removing .extension'''
            if application_name.split('.')[0] in ctx.name and ctx.isRunning:
                if ctx.name != sq.currentApplicationContext().name:
                    sq.setApplicationContext(ctx)
                    logger.debug("Switched context to: " + ctx.name)
                found = True

        if not found and application_name not in no_start_list:
            logger.debug("startApplication called for: " + application_name)

            if host is None:
                logger.debug("starting with application ONLY: " + application_name)
                # IMPORTANT - need to set application wrapper before attempting to start the app
                sq.testSettings.setWrappersForApplication(application_name, ('Windows'))
                sq.startApplication(application_name, host_ip, host_port)
            elif port is None:
                logger.debug("starting with application and HOST: " + application_name + " " + str(host))
                sq.testSettings.setWrappersForApplication(application_name, ('Windows'))
                sq.startApplication(application_name, host)
            else:
                logger.debug("starting with application, HOST and PORT: " +
                             application_name + " " + str(host) + " " + str(port))
                sq.testSettings.setWrappersForApplication(application_name, ('Windows'))
                sq.startApplication(application_name, host, builtins.int(port))


    @staticmethod
    def is_application_running(application_name):
        appCtxs = sq.applicationContextList()

        found = False
        for ctx in appCtxs:
            if application_name.split('.')[0] in ctx.name and ctx.isRunning:
                if ctx != sq.currentApplicationContext():
                    sq.setApplicationContext(ctx)
                found = True
        return found

    @staticmethod
    def killConsoleStart():

        hostname = sq.currentApplicationContext().host
        port = sq.currentApplicationContext().port

        try:
            remoteOS = RemoteSystem(hostname, port)

            taskkill = ['taskkill', '/IM', 'ConsoleStart.exe']
            (exitcode, stdout, stderr) = remoteOS.execute(taskkill)
            print("**********************    done trying to kill ConsoleStart   ***************************")
            print(exitcode)
            print(stdout)
            print(stderr)
        except Exception as e:
            logger.debug("Connect to squishserver failed", str(e))


    @staticmethod
    def launch_integrity_via_consolestart():

        # Now using attach to application process approach.
        logger.debug("startApplication called for HardwarePrep: " + str(sq.applicationContextList()))
        try:
            sq.attachToApplication("ConsoleStart")
        except Exception:
            try:
                ApplicationManager.launch_startwinaut(
                    Config.get("attach.ConsoleStart_batch_file"),
                    Config.get("attach.host"),
                    Config.get("attach.port"))
                sq.attachToApplication("ConsoleStart")

            except Exception:
                logger.debug("failed to attach to ConasoleStart, starting HardwarePrep: ")
                sq.startApplication(r"C:\WINDOWS\HardwarePrep.exe")

        logger.debug("Waiting for ConsoleStart to appear in AppCtxList: " + str(sq.applicationContextList()))

        # Wait for Unity to appear in application contexts
        ApplicationManager.wait_and_switch_to_application_in_appctx(ApplicationManager.APP_NAME_CONSOLESTART, int(0.01))
        logger.debug("ConsoleStart is now available in AppCtxList: " + str(sq.applicationContextList()))

        integrity_started = False
        timeout = 0
        while not integrity_started and timeout < 300:
            timeout += 1
            try:
                try:
                    sq.clickButton(sq.waitForObjectExists("{text='Start Now' type='Button'}", 0))
                    integrity_started = True
                    break
                except Exception as e:
                    logger.debug("Could not click the start button to launch automatically", str(e))

                sq.clickButton(sq.waitForObject(integrity_objs.precise_Desktop_Launch_Unity, 0))
                integrity_started = True
            except Exception:
                integrity_started = False
                try:
                    sq.clickButton(sq.waitForObject(integrity_objs.oK_Button, 0))
                except Exception:
                    sq.snooze(1)
        if not integrity_started:
            logger.critical("unity failed to start")

        logger.debug("Finished clicking OK buttons for ConsoleStart")

        ApplicationManager.wait_and_switch_to_application_in_appctx(ApplicationManager.APP_NAME_INTEGRITY)
        test.log(str(sq.applicationContextList()))  #type: ignore
        logger.debug("Context switched, now using: " + sq.currentApplicationContext().name)

    @staticmethod
    def wait_and_switch_to_application_in_appctx(application_name, timeout=60):

        end_time = time.time() + timeout
        found = False
        while (not found and (time.time() < end_time)):
            sq.snooze(5)
            appCtxs = sq.applicationContextList()
            print(appCtxs)
            for ctx in appCtxs:
                if application_name in ctx.name:
                    found = True
                    sq.setApplicationContext(ctx)
                    logger.debug("Found " + application_name + " in application context list")
                    return True
        return False


    @staticmethod
    def get_pid_by_image_name(application_name, host_address="", host_port=4322):
        '''
        Get process by application imagename from remote machine
        e.g. pid = ApplicationManager.get_pid_by_image_name("notepad++.exe", "192.168.40.128", host_port=4322)
        '''
        remotesys = RemoteSystem(host=host_address, port=host_port)
        (exitcode, stdout, stderr) = remotesys.execute(['cmd', '/c', 'tasklist'])
        if exitcode == '0':
            return stdout.split()[stdout.split().index(application_name) + 1]

    @staticmethod
    def detachApplicationContextsInList(ctx_name_list):
        # TODO: Add note as to when this is used
        appCtxs = sq.applicationContextList()
        logger.debug("detachApplicationContextsInList: " + str(ctx_name_list) + " ctxList: " + str(appCtxs))
        ctx_detached_list = []
        for ctx in appCtxs:
            if any(ctx.name in c for c in ctx_name_list):
                currentName = ctx.name
                ctx.detach()
                ctx_detached_list.append(currentName)

        if set(ctx_detached_list) == set(ctx_name_list):
            logger.debug("All contexts detached: " + str(ctx_name_list))
        else:
            logger.warning("Failed to detach all requested contexts " +
                           str(ctx_name_list) + ": " + str(sq.applicationContextList()))

    # ToT=Yes
    @staticmethod
    def launch_and_attach(application_name):

        #         Launch application via startwinaut and then attach to process.
        #         Expects batchfile config entry to be in the format '<app_name>_batch_file'

        try:
            host = Config.get("attach.host")
            port = Config.get("attach.port")
            batchfile = Config.get("attach." + application_name.lower() + "_batch_file")
            logger.debug("starting application " + application_name + " " + str(host) + " " + str(port))
            try:
                sq.attachToApplication(application_name)
            except Exception:
                ApplicationManager.launch_startwinaut(batchfile, host, port)
                sq.attachToApplication(application_name)

            ApplicationManager.wait_and_switch_to_application_in_appctx(application_name, timeout=30)
            logger.debug("Context after launch, wait and switch: " + str(sq.applicationContextList()))
            test.log("Context after launch, wait and switch: " + str(sq.applicationContextList()))  # type: ignore

            logger.debug("Attached to " + application_name)
            test.log("Attached to " + application_name) # type: ignore
            return True
        except Exception as e:
            logger.debug(str(e))

            logger.warning("Failed to launch and attach to " + application_name)
            # sq.startApplication(application_name)
            return False


    @staticmethod
    def launch_startwinaut(batch_file_path, host_address, host_port):
        #         This function executes a batch file on the host computer using the
        #            remotesystem object.
        try:
            try:
                remotesys = RemoteSystem(host_address, host_port)
            except Exception as f:
                remotesys = RemoteSystem()
        except Exception as e:
            logger.debug("Cannot connect to remote system", str(e))
            test.log("Error in remotesys object", str(e))   # type: ignore
            return False

        if not remotesys.exists(batch_file_path):
            logger.debug("Cannot find file - " + batch_file_path)
            return False

        tasklist = ["cmd", "/c", "start", "", "/min", batch_file_path]
        try:
            remotesys.execute(tasklist)
            sq.snooze(2)
        except Exception as e:
            logger.debug("Could not execute command on remote system", str(e))
            test.log("Error launching batch file", str(e))  # type: ignore
            return False

        return True


    @staticmethod
    def is_process_running(image_name):

        remotesys = RemoteSystem()
        (exitcode, stdout, stderr) = remotesys.execute(['cmd', '/c', 'tasklist'])
        process_running = image_name in stdout
        return process_running


    @staticmethod
    def attach_to_running_appplication(app_name, use_local_squishserver=False):
        '''
        attaches to running application with no need to register application, assign ports, use batch scripts or any other constantly re-occurring assigned parameters
        returns application context
        usage: sq.setApplicationContext(ApplicationManager.attach_to_running_appplication("notepad.exe"))
        '''

        try:
            if sq.currentApplicationContext().name == "RTDShell":
                sq.currentApplicationContext().detach()

            sq.attachToApplication(app_name)
        except Exception as e:
            if use_local_squishserver:
                host_ip = "127.0.0.1"
                # Get local squish installation paths from sharedconfig file
                squish_server_path = Config.get("system.local_squish_server", "D:\\squish\\Squish_runtime\\bin\\squishserver")
                squish_startwinaut_path = Config.get("system.local_squish_startwinaut", "D:\\squish\\Squish_runtime\\bin\\startwinaut")
            else:
                # Get host address from sharedconfig file
                host_ip = Config.get("attach.host")

                # Get remote squish installation paths from sharedconfig file
                squish_server_path = Config.get("system.squish_server", "D:\\squish\\Squish_runtime\\bin\\squishserver")
                squish_startwinaut_path = Config.get("system.squish_startwinaut", "D:\\squish\\Squish_runtime\\bin\\startwinaut")

            # Get squish server port from sharedconfig file
            host_port = Config.get_as_int("attach.port")

            logger.info("Cannot attach to image " + str(e))
            port = str(ApplicationManager.get_next_available_port())
            pid = str(ApplicationManager.get_pid_by_image_name(app_name, host_address=host_ip, host_port=host_port))
            remotesys = RemoteSystem(host=host_ip, port=host_port)
            remotesys.execute(['cmd', '/c', squish_server_path,
                               "--config", "addAttachableAUT", app_name, "localhost:" + port])
            '''snoozes required until a better way of checking is found'''
            sq.snooze(1)
            cwd = ""
            env = {}
            options = {'timeout': 5}
            remotesys.execute(['cmd',
                               '/c',
                               'start',
                               'Attachwinaut {}'.format(app_name),
                               '/min',
                               squish_startwinaut_path,
                               "--port=" + port,
                               "--pid=" + pid],
                              cwd,
                              env,
                              options)
            sq.snooze(5)
            return sq.attachToApplication(app_name, host_ip, host_port, 10000)


    @staticmethod
    def get_next_available_port():
        '''keeps a record of next available port - tried using an environment variable, but it isn't maintained'''
        temp_file_path = r"c:\temp"
        next_port_log = temp_file_path + r"\next_port"
        try:
            fh = open(next_port_log, "r")
            next_port =  builtins.int(fh.read())
            fh.close()
            fh = open(next_port_log, "w")
            fh.write(str(next_port + 1))
            fh.close()
            return next_port
        except Exception:
            '''restart port count if exception is thrown'''
            next_port = 6805
            if not os.path.exists(temp_file_path):
                os.makedirs(temp_file_path)
            fh = open(next_port_log, "w")
            fh.write(str(next_port + 1))
            fh.close()
            return next_port
